/*---
description: RegExp uses simple folding and does not expand sharp s into two ASCII letters.
features: [ts-unicode-regexp, ts-unicode-sequences, ts-strings, ts-arrays, ts-iteration, ts-tuples]
---*/
// Generated by tooling/unicode-cases/regexp.ts; Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, The design and Staying identical to node.
// Context: capital sharp s shares the Unicode class while full-fold SS is still two characters.
const pattern0 = /^\u00df$/i;
const pattern1 = /^\u00df$/iu;
const pattern2 = /^\u00df$/iv;
const samples: [string, boolean, boolean, boolean][] = [
  ["\u00df", true, true, true],
  ["\u1e9e", false, true, true],
  ["\u0053\u0053", false, false, false],
  ["\u0073\u0073", false, false, false],
  ["\u0073", false, false, false],
];
for (const sample of samples) {
  assert.sameValue(pattern0.test(sample[0]), sample[1], "sharp-s-not-full-fold pattern 0");
  assert.sameValue(pattern1.test(sample[0]), sample[2], "sharp-s-not-full-fold pattern 1");
  assert.sameValue(pattern2.test(sample[0]), sample[3], "sharp-s-not-full-fold pattern 2");
}
